from solution import char_frequency


def test_issue_example_python():
    """Example char_frequency('python') maps each letter to 1."""
    # hand count: p:1, y:1, t:1, h:1, o:1, n:1; total 1*6=6
    assert char_frequency('python') == {'p': 1, 'y': 1, 't': 1, 'h': 1, 'o': 1, 'n': 1}


def test_issue_empty_string():
    """Count character frequency of a given string with empty input."""
    # hand count: len("")=0, no chars so total 0
    assert char_frequency('') == {}


def test_issue_single_character():
    """Count character frequency of a given single-character string."""
    # hand count: 'a' appears once; 1=1
    assert char_frequency('a') == {'a': 1}


def test_issue_all_same_character():
    """Count character frequency of a given string with one repeated character."""
    # hand count: 'b' appears 1+1+1+1=4
    assert char_frequency('bbbb') == {'b': 4}


def test_issue_mixed_repeats_hello():
    """Count character frequency of a given string with mixed repeats."""
    # hand count: h:1, e:1, l:1+1=2, o:1; total 1+1+2+1=5
    assert char_frequency('hello') == {'h': 1, 'e': 1, 'l': 2, 'o': 1}


def test_issue_spaces_are_counted():
    """Count character frequency of a given string including spaces."""
    # hand count: 'a':1, ' ':1, 'b':1; total 1+1+1=3
    assert char_frequency('a b') == {'a': 1, ' ': 1, 'b': 1}


def test_issue_digits_are_counted():
    """Count character frequency of a given string including digits."""
    # hand count: 'a':1, '1':1+1=2; total 1+2=3
    assert char_frequency('a11') == {'a': 1, '1': 2}


def test_issue_case_sensitive():
    """Count character frequency of a given string with distinct cases."""
    # hand count: 'A':1, 'a':1; total 1+1=2
    assert char_frequency('Aa') == {'A': 1, 'a': 1}


def test_issue_punctuation_counted():
    """Count character frequency of a given string including punctuation."""
    # hand count: 'a':1, '!':1+1=2, 'b':1; total 1+2+1=4
    assert char_frequency('a!!b') == {'a': 1, '!': 2, 'b': 1}


def test_contract_returns_dict():
    """Count character frequency of a given string returns a dict."""
    # expected type dict as in example {'p': 1}; check instance
    assert isinstance(char_frequency('abc'), dict)


def test_contract_values_sum_to_length():
    """Count character frequency of a given string sums to input length."""
    # hand count for 'abca': a:1+1=2, b:1, c:1; sum 2+1+1=4, len=4
    assert sum(char_frequency('abca').values()) == 4


def test_contract_keys_match_characters():
    """Count character frequency of a given string keys are input characters."""
    # hand count for 'abca': distinct a,b,c = 3 keys from 2+1+1=4 chars
    assert set(char_frequency('abca').keys()) == {'a', 'b', 'c'}
